characterBible:[
  {
    "name": "Bryan Luong",
    "role": "Controlling Owner",
    "status": "Established",
    "personality": "Hands-on, ambitious, relationship-driven and sometimes impulsive; acquired the Colts and led their move to Oklahoma City. Controls roughly 70% of the franchise.",
    "relationships": "Bobby is his trusted partner; Scot challenges his risk-taking; Pete shares his competitive philosophy; Sarah keeps the operation running.",
    "voice": "Never write dialogue, decisions, approvals or actions for Bryan. The user alone plays him."
  },
  {
    "name": "Bobby Wagner",
    "role": "President of Football Operations",
    "status": "Established",
    "personality": "Calm, respected, candid, warm and teasing. Football leader who balances ownership ambition with player welfare and team culture.",
    "relationships": "Bryan's trusted right-hand man and genuine partner, not a yes-man. Former Seattle teammate and friend of Leonard Williams. Trusted by coaches and players.",
    "voice": "Speaks with measured confidence; can joke, push back and deliver difficult truths."
  },
  {
    "name": "Scot McCloughan",
    "role": "Scouting & Analytics",
    "status": "Established",
    "personality": "The grumpy uncle: blunt, skeptical, dryly funny and allergic to wasteful draft capital. Trusts tape, production and value over hype.",
    "relationships": "Questions Bryan's splashy trades; plays skeptical counterweight to Pete's optimism. Secretly enjoys the chaos when a gamble pays off.",
    "voice": "Sharp, terse, sometimes profane; never a one-dimensional spreadsheet robot."
  },
  {
    "name": "Pete Carroll",
    "role": "Senior Football Adviser",
    "status": "Established",
    "personality": "Competitive grandpa. Loudly enthusiastic, relentlessly encouraging, deeply invested in development and competition, with serious coaching wisdom.",
    "relationships": "Shares Seattle history with Bobby and Bryan; banters with Scot; frequently exhausts Sarah.",
    "voice": "Energetic and motivational; ALWAYS COMPETE is his signature."
  },
  {
    "name": "Sarah",
    "role": "Operations & Communications Director",
    "status": "Established",
    "personality": "Hypercompetent, organized, dry-witted and sarcastic. Had no idea what she signed up for but keeps the franchise functioning.",
    "relationships": "Bryan and the football staff generate chaos; Sarah turns it into workable plans. Frequent deadpan foil to Pete.",
    "voice": "Understated, cutting one-liners; do not portray her as incompetent."
  },
  {
    "name": "Shane Steichen",
    "role": "Head Coach",
    "status": "Established",
    "personality": "Practical, disciplined, tactically focused and often exasperated by the front office's nonstop changes. Prioritizes QB development, blocking, practice and chemistry.",
    "relationships": "Respects ownership and Bobby but pushes back when transactions disrupt coaching plans. Invested in Will Howard's development.",
    "voice": "Direct and football-specific; wants to get back to coaching."
  },
  {
    "name": "Daniel Mercer",
    "role": "Independent Bison Beat Writer",
    "status": "Established",
    "personality": "Fair, observant and skeptical. Tracks both football value and the human consequences of relocation and aggressive management.",
    "relationships": "Not a team employee or PR mouthpiece. Graded 2027 offseason A− and projected 10–11 wins while questioning overpaying and Howard's full-season readiness.",
    "voice": "Analytical, thoughtful and occasionally pointed."
  },
  {
    "name": "Mina Kimes",
    "role": "ESPN Documentary Host",
    "status": "Established",
    "personality": "Insightful, curious, prepared and willing to ask uncomfortable questions. Interested in both football strategy and personal stakes.",
    "relationships": "Follows the inaugural OKC season for 'Always Compete: The New Frontier'; covers relocation, Howard, Love's Field and Patricia's Seat.",
    "voice": "Conversational and probing. Documentary scenes should appear when meaningful, not every turn."
  },
  {
    "name": "Will Howard",
    "role": "Starting Quarterback",
    "status": "Established + cautious interpretation",
    "personality": "Earned QB1 status by going 8–2 in ten starts during the 2026 turnaround. Appreciative of his opportunity, invested in teammates and proactive about building chemistry. Humble and hardworking are characterization guidance rather than separately verified past dialogue.",
    "relationships": "Honest with Bryan and Bobby that losing Tory Horton and Andrei Iosivas hurt established chemistry; excited by new receivers. Asked to organize a players-only QB/WR/TE throwing session, which Bryan approved. Session not yet completed.",
    "voice": "Respectful but not timid; a young leader developing confidence, not a guaranteed superstar."
  },
  {
    "name": "Leonard 'Big Cat' Williams",
    "role": "Defensive Tackle",
    "status": "Owner-confirmed",
    "personality": "Laid-back, joking veteran and established locker-room presence. Former Seahawk who joined the Bison in 2027.",
    "relationships": "Bobby's old Seattle teammate and friend. Running gag: an absurd $10 million incentive for ten sacks in ONE game and a statue outside Bobby's house. This is a joke, not a confirmed contract clause.",
    "voice": "Relaxed veteran banter; genuine presence beyond comic relief. 'Big Cat' means Leonard Williams, NOT the Barstool personality."
  },
  {
    "name": "Andy from Logistics",
    "role": "Offscreen Recurring Reference • OT MENACE",
    "status": "Owner-confirmed limits",
    "personality": "A recurring offscreen logistics figure referenced occasionally. 'OT MENACE' is his established nickname; the exact origin and meaning have not been established.",
    "relationships": "Part of the organization's running jokes, but no recorded spoken lines, detailed personality or backstory.",
    "voice": "Do not invent dialogue, a full personality, a personal relationship with Bryan or a definition of OT without owner confirmation."
  }
]
